1	"use client";
2	
3	// Client-side currency context: holds the visitor's active DISPLAY currency + the
4	// FX rates table (both resolved on the server per-request and passed down through
5	// the layout), lets a manual switcher override the geo guess, and persists that
6	// override to a cookie so it survives navigation and reloads.
7	//
8	// DISPLAY ONLY. The formatter this exposes converts a USD-cents amount to a
9	// localized string; it never changes what a customer is charged. See the boundary
10	// note in lib/currency.ts.
11	
12	import { createContext, useCallback, useContext, useMemo, useState } from "react";
13	import {
14	  CURRENCIES,
15	  CURRENCY_COOKIE,
16	  DEFAULT_CURRENCY,
17	  convertAndFormat,
18	  rateFor,
19	} from "@/lib/currency";
20	
21	type CurrencyContextValue = {
22	  /** Active display currency code (always a key of CURRENCIES). */
23	  currency: string;
24	  /** Full rates table (target units per USD). */
25	  rates: Record<string, number>;
26	  /** The active currency's rate — > 0. */
27	  rate: number;
28	  /** Override the geo/default guess and persist it to a cookie. */
29	  setCurrency: (code: string) => void;
30	  /** Convert a USD-cents amount and format it in the active currency. */
31	  format: (baseUsdCents: number) => string;
32	};
33	
34	const CurrencyContext = createContext<CurrencyContextValue | null>(null);
35	
36	/** ~1 year, so a deliberate choice sticks. */
37	const COOKIE_MAX_AGE = 60 * 60 * 24 * 365;
38	
39	export function CurrencyProvider({
40	  initialCurrency,
41	  rates,
42	  children,
43	}: {
44	  initialCurrency: string;
45	  rates: Record<string, number>;
46	  children: React.ReactNode;
47	}) {
48	  const normalizedInitial =
49	    initialCurrency && CURRENCIES[initialCurrency.toUpperCase()]
50	      ? initialCurrency.toUpperCase()
51	      : DEFAULT_CURRENCY;
52	  const [currency, setCurrencyState] = useState(normalizedInitial);
53	
54	  const setCurrency = useCallback((code: string) => {
55	    const next = (code || "").toUpperCase();
56	    if (!CURRENCIES[next]) return;
57	    setCurrencyState(next);
58	    if (typeof document !== "undefined") {
59	      document.cookie = `${CURRENCY_COOKIE}=${next}; path=/; max-age=${COOKIE_MAX_AGE}; SameSite=Lax`;
60	    }
61	  }, []);
62	
63	  const value = useMemo<CurrencyContextValue>(() => {
64	    const rate = rateFor(rates, currency);
65	    return {
66	      currency,
67	      rates,
68	      rate,
69	      setCurrency,
70	      format: (baseUsdCents: number) => convertAndFormat(baseUsdCents, currency, rate),
71	    };
72	  }, [currency, rates, setCurrency]);
73	
74	  return <CurrencyContext.Provider value={value}>{children}</CurrencyContext.Provider>;
75	}
76	
77	/**
78	 * Full currency context. Safe to call outside a provider — it degrades to a USD,
79	 * no-op formatter so a component rendered without the provider (e.g. in isolation)
80	 * still shows correct USD prices rather than throwing.
81	 */
82	export function useCurrency(): CurrencyContextValue {
83	  const ctx = useContext(CurrencyContext);
84	  if (ctx) return ctx;
85	  return {
86	    currency: DEFAULT_CURRENCY,
87	    rates: { USD: 1 },
88	    rate: 1,
89	    setCurrency: () => {},
90	    format: (baseUsdCents: number) => convertAndFormat(baseUsdCents, DEFAULT_CURRENCY, 1),
91	  };
92	}
93	
94	/**
95	 * The price formatter alone: `const money = useDisplayMoney()` gives a
96	 * `(usdCents) => string` that converts to the visitor's active currency. Drop-in
97	 * for the local `money()` helpers each price component used to define.
98	 */
99	export function useDisplayMoney(): (baseUsdCents: number) => string {
100	  return useCurrency().format;
101	}
