1	"use client";
2	
3	import { useState } from "react";
4	import Link from "next/link";
5	import { IconCheck } from "./icons";
6	import { planTip, planAudience } from "./planTips";
7	import { termPriceCents, ANNUAL_TERM_MONTHS } from "@/lib/billing-terms";
8	import { useDisplayMoney } from "@/components/currency/CurrencyContext";
9	
10	export type PlanCard = {
11	  id: string;
12	  name: string;
13	  cpuCores: number;
14	  ramMB: number;
15	  diskGB: number;
16	  bandwidthTB: number;
17	  priceCents: number;
18	  storageTier: string;
19	};
20	
21	function planFeatures(p: PlanCard): string[] {
22	  const disk = p.storageTier === "hdd" ? "HDD storage" : "NVMe SSD storage";
23	  return [
24	    `${p.cpuCores} vCPU core${p.cpuCores > 1 ? "s" : ""}`,
25	    `${(p.ramMB / 1024).toFixed(p.ramMB % 1024 ? 1 : 0)} GB RAM`,
26	    `${p.diskGB} GB ${disk}`,
27	    `${p.bandwidthTB} TB bandwidth`,
28	    "Full root access",
29	    "Free DDoS protection",
30	  ];
31	}
32	
33	export function PricingGrid({ plans, annualPct = 0 }: { plans: PlanCard[]; annualPct?: number }) {
34	  // Prices are USD-cents in the DB; `money` converts them to the visitor's display
35	  // currency (geo/manual) for rendering only — checkout still charges the USD amount.
36	  const money = useDisplayMoney();
37	  // Billing toggle — Annual is on by default when it's a real discount, so the
38	  // headline price shows the better-value figure first. Switching to Monthly shows
39	  // the undiscounted monthly price. Every figure is DB-fed through termPriceCents,
40	  // the SAME formula checkout charges — displayed === charged.
41	  const annualAvailable = annualPct > 0;
42	  const [annual, setAnnual] = useState(true);
43	  const showAnnual = annual && annualAvailable;
44	
45	  // Highlight the middle plan (by position) as "Most popular"; the top (most
46	  // expensive) plan gets a "Best value / most resources" anchor so the mid tier
47	  // reads as the smart buy.
48	  const popularIdx = plans.length ? Math.floor((plans.length - 1) / 2) : -1;
49	  const topIdx = plans.length >= 3 ? plans.length - 1 : -1;
50	  const fromCents = plans.length ? Math.min(...plans.map((p) => p.priceCents)) : 0;
51	  const topCents = plans.length ? Math.max(...plans.map((p) => p.priceCents)) : 0;
52	
53	  if (plans.length === 0) {
54	    return (
55	      <div className="card text-center text-slate-400">
56	        Plans are being provisioned. Please check back shortly.
57	      </div>
58	    );
59	  }
60	
61	  // No promo banner here: first-month-free is a Shared Web Hosting offer only
62	  // (see lib/promo-redemption.ts firstMonthFreeAppliesTo). VPS bills the regular
63	  // price from month one — the price shown IS what checkout charges.
64	
65	  return (
66	    <div>
67	      {annualAvailable && (
68	        <div className="mb-8 flex flex-col items-center gap-2">
69	          <div className="inline-flex items-center rounded-full border border-white/10 bg-navy-900/70 p-1 backdrop-blur">
70	            <button
71	              type="button"
72	              aria-pressed={!annual}
73	              onClick={() => setAnnual(false)}
74	              className={`rounded-full px-5 py-1.5 text-sm font-semibold transition-colors ${
75	                !annual ? "bg-white/10 text-white" : "text-slate-400 hover:text-white"
76	              }`}
77	            >
78	              Monthly
79	            </button>
80	            <button
81	              type="button"
82	              aria-pressed={annual}
83	              onClick={() => setAnnual(true)}
84	              className={`flex items-center gap-2 rounded-full px-5 py-1.5 text-sm font-semibold transition-colors ${
85	                annual ? "bg-gradient-to-r from-accent-blue to-brand-500 text-white shadow" : "text-slate-400 hover:text-white"
86	              }`}
87	            >
88	              Annual
89	              <span className={`rounded-full px-1.5 py-0.5 text-[10px] font-bold ${annual ? "bg-white/20 text-white" : "bg-emerald-500/15 text-emerald-300"}`}>
90	                –{annualPct}%
91	              </span>
92	            </button>
93	          </div>
94	          <p className="text-xs text-slate-500">
95	            {showAnnual ? "Billed yearly · cancel anytime" : "Billed monthly · switch to annual to save"}
96	          </p>
97	        </div>
98	      )}
99	      <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
100	        {plans.map((p, i) => {
101	          const popular = i === popularIdx;
102	          const topTier = i === topIdx;
103	          const regular = p.priceCents;
104	          // Effective $/mo on the annual term — DB-fed via the shared term formula,
105	          // the same one checkout charges. Only shown when annual is a real discount.
106	          const annualPerMo = annualAvailable ? Math.round(termPriceCents(regular, ANNUAL_TERM_MONTHS, annualPct) / ANNUAL_TERM_MONTHS) : 0;
107	          const annualTotal = annualAvailable ? termPriceCents(regular, ANNUAL_TERM_MONTHS, annualPct) : 0;
108	          const bigCents = showAnnual ? annualPerMo : regular;
109	          return (
110	          <div
111	            key={p.id}
112	            className={`group relative flex flex-col rounded-2xl border p-6 backdrop-blur-md transition-all duration-300 hover:-translate-y-1.5 ${
113	              popular
114	                ? "border-brand-500/40 bg-navy-850/80 glow-brand"
115	                : "border-white/[0.06] bg-navy-900/70 hover:border-brand-500/30 hover:bg-navy-850/70 hover:shadow-[0_0_40px_-10px_rgb(111_71_245_/_0.4)]"
116	            }`}
117	          >
118	            {popular && (
119	              <span className="absolute -top-3 left-1/2 -translate-x-1/2 rounded-full bg-gradient-to-r from-accent-blue to-brand-500 px-3 py-1 text-[11px] font-semibold uppercase tracking-wider text-white shadow-lg">
120	                Most popular
121	              </span>
122	            )}
123	            {topTier && !popular && (
124	              <span className="absolute -top-3 right-4 rounded-full border border-white/10 bg-navy-950 px-2.5 py-1 text-[10px] font-semibold uppercase tracking-wider text-slate-300 shadow-lg">
125	                Best value
126	              </span>
127	            )}
128	            <div className="flex items-center justify-between">
129	              <h3 className="text-base font-semibold text-white">{p.name}</h3>
130	              <span className="rounded-full border border-brand-500/30 bg-brand-500/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wider text-brand-300">
131	                {topTier ? "Most resources" : planAudience(p)}
132	              </span>
133	            </div>
134	            <div className="mt-3">
135	              <div className="flex items-end gap-1">
136	                <span className="text-4xl font-bold tracking-tight">{money(bigCents)}</span>
137	                <span className="mb-1 text-sm text-slate-400">/mo</span>
138	              </div>
139	              {showAnnual ? (
140	                <p className="mt-1 text-[11px] leading-snug text-emerald-300">
141	                  {money(annualTotal)} billed yearly — save {annualPct}% vs {money(regular)}/mo
142	                </p>
143	              ) : annualAvailable ? (
144	                <p className="mt-1 text-[11px] leading-snug text-slate-500">
145	                  or {money(annualPerMo)}/mo billed annually — save {annualPct}%
146	                </p>
147	              ) : (
148	                <p className="mt-1 text-[11px] leading-snug text-slate-500">
149	                  Billed monthly. Cancel anytime.
150	                </p>
151	              )}
152	            </div>
153	            <div className="mt-4 flex items-start gap-2 rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
154	              <span className="mt-0.5 text-brand-300" aria-hidden>
155	                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
156	                  <path d="M9 18h6M10 21h4M12 2a7 7 0 0 0-4 12.7c.6.5 1 1.3 1 2.1h6c0-.8.4-1.6 1-2.1A7 7 0 0 0 12 2z" />
157	                </svg>
158	              </span>
159	              <p className="text-[12px] leading-snug text-slate-300">
160	                <span className="font-semibold text-slate-200">Great for: </span>
161	                {planTip(p)}
162	              </p>
163	            </div>
164	            <ul className="mt-5 flex-1 space-y-3 text-sm">
165	              {planFeatures(p).map((f) => (
166	                <li key={f} className="flex items-center gap-2.5 text-slate-300">
167	                  <span className="flex h-4.5 w-4.5 shrink-0 items-center justify-center rounded-full bg-brand-500/15 text-brand-300">
168	                    <IconCheck size={12} />
169	                  </span>
170	                  {f}
171	                </li>
172	              ))}
173	            </ul>
174	            <Link
175	              href="/register"
176	              className={`mt-7 w-full ${popular ? "btn-deploy" : "btn-secondary"}`}
177	            >
178	              Deploy now
179	            </Link>
180	          </div>
181	          );
182	        })}
183	      </div>
184	      <p className="mt-6 text-center text-sm text-slate-500">
185	        From <span className="font-semibold text-slate-300">{money(fromCents)}</span> to{" "}
186	        <span className="font-semibold text-slate-300">{money(topCents)}/mo</span> — every tier gets the same platform, root access and protection; you only choose the horsepower.
187	        {annualPct > 0 && (
188	          <>
189	            {" "}Prefer to pay yearly?{" "}
190	            <span className="font-semibold text-emerald-300">Annual billing saves {annualPct}%</span> — choose your term in the deploy wizard.
191	          </>
192	        )}
193	      </p>
194	    </div>
195	  );
196	}
