1	"use client";
2	
3	import { useMemo, useRef, useState } from "react";
4	import { useActionState, useEffect } from "react";
5	import { payAndDeploy, previewOrderCoupon } from "@/lib/actions";
6	import { AppLogo } from "@/components/ui/AppLogo";
7	import { StripeCheckoutModal } from "@/components/customer/StripeCheckoutModal";
8	import { VersionPickerModal, type FamilyGroup } from "@/components/customer/VersionPickerModal";
9	// No vpsTermPriceCents here any more: every term price this wizard shows is now
10	// derived from lib/renewal-quote.ts (the regular/renewal rate) with the promo
11	// applied on top, so the file has exactly one source for what a term costs.
12	import { VPS_TERMS, vpsTerm, ANNUAL_TERM_MONTHS, DEFAULT_ANNUAL_DISCOUNT_PCT } from "@/lib/billing-terms";
13	import { renewalQuote } from "@/lib/renewal-quote";
14	import { walletSplit } from "@/lib/wallet-split";
15	import {
16	  EXTRA_DISK_MAX_ADD_GB,
17	  EXTRA_DISK_MIN_GB,
18	  EXTRA_DISK_ONE_WAY_NOTE,
19	  EXTRA_DISK_STEP_GB,
20	  effectiveDiskGB,
21	  extraDiskCentsAt,
22	} from "@/lib/extra-disk";
23	
24	type Plan = {
25	  id: string; name: string; cpuCores: number; ramMB: number; diskGB: number;
26	  bandwidthTB: number; priceCents: number; storageTier: string;
27	};
28	type Image = {
29	  id: string; slug: string; name: string; category: string; family: string;
30	  version: string; logo: string; minRamMB: number; minDiskGB: number;
31	  licenseRequired: boolean; featured: boolean;
32	};
33	type NodeOpt = { id: string; name: string; publicIp: string };
34	
35	const money = (c: number) => `$${(c / 100).toFixed(2)}`;
36	
37	/** sessionStorage key for the in-progress order — see the restore effect below. */
38	const DRAFT_KEY = "nxeon.deploy.draft.v1";
39	type Draft = {
40	  step: number;
41	  planId: string;
42	  nodeId: string;
43	  imageId: string;
44	  tab: string;
45	  addons: { malware: boolean; backup: boolean; docker: boolean };
46	  dedicatedIp: boolean;
47	  extraDiskGB: number;
48	  hostname: string;
49	  pubKey: string;
50	  termMonths: number;
51	  useWallet: boolean;
52	};
53	
54	/** APPLICATION-category images with one of these families are split into the Games tab. */
55	const GAME_FAMILIES = new Set(["minecraft", "valheim", "rust", "palworld", "cs2", "terraria"]);
56	
57	/** Install-step tabs. Games are peeled out of Applications into their own tab. */
58	const TABS = [
59	  { key: "os", label: "Operating Systems", match: (i: Image) => i.category === "PLAIN_OS" },
60	  { key: "panels", label: "Control Panels", match: (i: Image) => i.category === "CONTROL_PANEL" },
61	  { key: "apps", label: "Applications", match: (i: Image) => i.category === "APPLICATION" && !GAME_FAMILIES.has(i.family) },
62	  { key: "games", label: "Games", match: (i: Image) => i.category === "APPLICATION" && GAME_FAMILIES.has(i.family) },
63	] as const;
64	
65	const OS_FAMILY_NAMES: Record<string, string> = {
66	  ubuntu: "Ubuntu", debian: "Debian", almalinux: "AlmaLinux", rocky: "Rocky Linux",
67	  fedora: "Fedora", centos: "CentOS", arch: "Arch Linux", alpine: "Alpine", kali: "Kali Linux", opensuse: "openSUSE",
68	};
69	/**
70	 * Human name for an image on the confirmation screen.
71	 *
72	 * Catalogue rows carry the version in BOTH `name` ("Ubuntu 20.04") and `version`
73	 * ("20.04"), so appending unconditionally printed "Ubuntu 20.04 20.04" — on the
74	 * last screen before the customer pays. Only append a version the name does not
75	 * already end with.
76	 */
77	function imageLabel(img: Image) {
78	  const version = img.version?.trim();
79	  if (!version) return img.name;
80	  return img.name.trim().endsWith(version) ? img.name : `${img.name} ${version}`;
81	}
82	
83	/** Clean family display name (no version) for the OS family cards. */
84	function osFamilyName(img: Image) {
85	  return OS_FAMILY_NAMES[img.family] ?? img.name.replace(/\s+\d.*$/, "").trim() ?? img.family;
86	}
87	
88	function Stepper({ step, steps }: { step: number; steps: string[] }) {
89	  return (
90	    <div className="mb-6 flex flex-wrap items-center gap-2 text-xs">
91	      {steps.map((s, i) => (
92	        <div key={s} className="flex items-center gap-2">
93	          <span
94	            className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] font-semibold ${
95	              i === step ? "border-brand-400 bg-brand-500/20 text-brand-200"
96	                : i < step ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300"
97	                  : "border-white/10 text-slate-500"
98	            }`}
99	          >
100	            {i < step ? "✓" : i + 1}
101	          </span>
102	          <span className={i === step ? "text-white" : "text-slate-500"}>{s}</span>
103	          {i < steps.length - 1 && <span className="mx-1 text-slate-700">→</span>}
104	        </div>
105	      ))}
106	    </div>
107	  );
108	}
109	
110	export function DeployWizard({
111	  plans, images, nodes, sshKeys, isAdmin, balanceCents, dedicatedIpAvailable, dedicatedIpPriceCents,
112	  extraDiskPriceCentsPerGb = 0,
113	  backupPlusPriceCents = 0,
114	  defaultPlanId, defaultTermMonths,
115	  promoPercent = 0, promoLabel,
116	  annualDiscountPct = DEFAULT_ANNUAL_DISCOUNT_PCT,
117	  taxRatePercent = 0, taxCountry = "",
118	}: {
119	  plans: Plan[]; images: Image[]; nodes: NodeOpt[];
120	  sshKeys: { id: string; name: string }[]; isAdmin: boolean; balanceCents: number;
121	  dedicatedIpAvailable?: boolean; dedicatedIpPriceCents?: number;
122	  /**
123	   * Price per GB per month for extra ROOT DISK (admin setting
124	   * `extra_disk_gb_price_cents`). Priced over the term exactly like the dedicated
125	   * IP add-on, so the maths here matches lib/order.ts orderQuote byte-for-byte.
126	   * 0 hides the upsell entirely.
127	   */
128	  extraDiskPriceCentsPerGb?: number;
129	  /**
130	   * Monthly price of the Plus backup-retention tier (admin setting
131	   * `backup_plus_price_cents`). Priced over the term like the other add-ons so this
132	   * matches lib/order.ts orderQuote byte-for-byte.
133	   */
134	  backupPlusPriceCents?: number;
135	  /**
136	   * Plan pre-selected on step 1, from the `default_plan_slug` admin setting.
137	   *
138	   * An **id**, not the slug the setting stores: this component's `Plan` type carries no
139	   * slug, so matching here would mean widening the payload or matching on `name`. The
140	   * page resolves slug → id against the very array it passes down, so any id arriving
141	   * here is guaranteed to be in `plans`; a stale slug (plan renamed, or deactivated)
142	   * arrives as `undefined` and the wizard falls back to the first plan rather than
143	   * opening with nothing selected and no price on the Review step.
144	   */
145	  defaultPlanId?: string;
146	  /**
147	   * Billing term pre-selected on the Review step, in MONTHS, from `default_term`.
148	   *
149	   * Guaranteed by `defaultTermMonths()` to be one of `VPS_TERMS`. That guarantee is
150	   * load-bearing: the term buttons below are rendered straight from `VPS_TERMS` and
151	   * highlight on `termMonths === t.months`, so an unlisted value (the old setting's
152	   * "quarterly", say) would render a Review step with no term highlighted while the
153	   * hidden `termMonths` field still posted it — and `vpsTerm()` silently falls back to
154	   * monthly, so the customer would be charged for a term nothing on screen showed.
155	   */
156	  defaultTermMonths?: number;
157	  /** Active intro-promo discount (%) on the FIRST term — matches what payAndDeploy charges. */
158	  promoPercent?: number; promoLabel?: string;
159	  /**
160	   * The admin ANNUAL discount (`annual_discount_percent`), resolved server-side and
161	   * passed in so the Annual term card's price, savings and `−X%` badge are the REAL
162	   * configured rate — the same one lib/order.ts charges and renewalCharge renews at.
163	   * Threaded into `renewalQuote` below so displayed === charged === renewed. Only
164	   * affects the 12-month card; every other term keeps its fixed rate.
165	   */
166	  annualDiscountPct?: number;
167	  /**
168	   * Destination VAT/GST rate (%) for THIS customer's billing country (Finding 1),
169	   * resolved server-side (lib/tax.ts taxContextForUser). 0 (the default, and the case
170	   * for any customer with no billing country on file) adds no tax and leaves the total
171	   * exactly as before. When > 0 the summary shows a tax line and `dueCents` is made
172	   * tax-inclusive, so what is shown here === what payAndDeploy charges.
173	   */
174	  taxRatePercent?: number;
175	  taxCountry?: string;
176	}) {
177	  const [state, action, pending] = useActionState(
178	    payAndDeploy,
179	    {} as { error?: string; checkout?: { clientSecret: string; publishableKey: string } },
180	  );
181	  // The embedded Stripe session to mount in a modal on THIS page (no redirect),
182	  // set only on an explicit Deploy submit (see submittedRef below).
183	  const [checkoutSession, setCheckoutSession] = useState<{ clientSecret: string; publishableKey: string } | null>(null);
184	  // Apply the first-term promo to any regular price, mirroring promoPriceCents()
185	  // in lib/promotions.ts so the wizard's displayed price === the checkout charge.
186	  const hasPromo = promoPercent > 0;
187	  const promoCents = (regular: number) => Math.round(regular * (1 - promoPercent / 100));
188	  // Only redirect to Stripe as the result of an EXPLICIT Deploy submit. The flag is
189	  // armed in the Deploy button's onClick (and the Enter-on-final-step path) and
190	  // consumed here, so a stale `checkoutUrl` in state can never redirect on its own —
191	  // e.g. after a back-button remount (ref starts false) or an unrelated re-render.
