748	/** A short URL-safe idempotency token (no external uuid dependency). */
749	function makeToken(): string {
750	  try {
751	    if (typeof crypto !== "undefined" && "randomUUID" in crypto) return crypto.randomUUID().replace(/-/g, "");
752	  } catch {
753	    /* fall through */
754	  }
755	  return `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 12)}`;
756	}
